            int pre = n - cnt;
            long long comb = (ncr[n][pre] * fact[pre]) % mod;
            if(comb == 0) comb += mod;
            long long sum=0;

            for(int dif=1; dif<cnt; dif++){
                for(int inv=dif; inv<(int)dp[0].size(); inv++){
